from ...mbms_sessions.mbms_session import MbmsSession


class DemoMbmsSession(MbmsSession):
    """Object responsible for managing IPHY mbms session."""

    def __init__(self, *args, **kwargs):
        """

        :param args:
        :param kwargs:
        """
        super().__init__(*args, **kwargs)
        self.logger.info(f'"{self.name}" instance of DemoMbmsSession created: ')
        self.is_verification_in_progress = False

    def start_verifying(self):
        """
        Starts verifying mbsm session
        :return: None
        """
        self.is_verification_in_progress = True
        self.logger.info(f'DemoMbmsSession "{self.name}": start_verifying')

    def stop_verifying(self):
        """
        Stops verifying mbms session

        Fires exception if given mbms session (selected by it's name) was not listened yet.
        No action if given mbms session is not listened
        :return: None
        """
        self.is_verification_in_progress = False
        self.logger.info(f'DemoMbmsSession "{self.name}": stop_verifying')

    def is_being_verified(self):
        """
        Check if mbms session is being verified

        :return: boolean
        """
        return self.is_verification_in_progress

    def get_success_rate(self):
        """
        Getting success rate of mbms session.
        success rate is measured from 'mbms_session.start_listening()' to current time or
        from 'mbms_session.start_listening()' to 'mbms_session.stop_listening()' if mbms session listening is finished
        :return: success rate in unit: %
        """
        pass

    def reset_statistics(self):
        """
        Resetting statistics of mbms session.
        :return: None
        """
        pass
